 "content": "def transform(grid):
    # Full separator rows and columns divide the grid into panels. Mark a
    # panel with 1 when it contains an orthogonally adjacent pair of marks.
    h, w = len(grid), len(grid[0])
    divider = next((v for v in range(10)
                    if any(all(x == v for x in row) for row in grid)
                    and any(all(grid[r][c] == v for r in range(h)) for c in range(w))), None)
    if divider is None:
        return grid
    from collections import Counter
    counts = Counter(x for row in grid for x in row if x != divider)
    background = counts.most_common(1)[0][0]
    mark = next(v for v in counts if v != background)

    def spans(indices):
        result = []
        for i in indices:
            if not result or i != result[-1][-1] + 1:
                result.append([i])
            else:
                result[-1].append(i)
        return result

    row_spans = spans([r for r in range(h) if not all(x == divider for x in grid[r])])
    col_spans = spans([c for c in range(w) if not all(grid[r][c] == divider for r in range(h))])
    output = []
    for rows in row_spans:
        out_row = []
        for cols in col_spans:
            marks = {(r, c) for r in rows for c in cols if grid[r][c] == mark}
            adjacent = any((r + dr, c + dc) in marks
                           for r, c in marks for dr, dc in ((1, 0), (0, 1)))
            out_row.append(1 if adjacent else background)
        output.append(out_row)
    return output
